/// A JSON Schema for a Swift type, usually generated by `@Schema`.
///
/// Named schemas (`object`, `enumeration`, `union`, `taggedUnion`) are inlined by ``json`` and ``strict()`` and become
/// `components/schemas` references in the OpenAPI document.
public indirect enum JSONSchema: Sendable {
    case string(format: String? = nil)
    case integer(format: String? = nil)
    case number(format: String? = nil)
    case boolean
    /// Any JSON value.
    case any
    case array(items: JSONSchema)
    /// `[String: T]`.
    case map(values: JSONSchema)
    case object(name: String, description: String?, properties: [Property])
    case enumeration(name: String, description: String?, values: [JSONValue])
    /// An enum whose cases each wrap one value, encoded as that value: `anyOf` the variants.
    case union(name: String, description: String?, variants: [JSONSchema])
    /// An enum whose cases each wrap a `@Schema` struct, encoded as that struct's object plus the `tag` key set to the
    /// case's tag value: `anyOf` the variant objects, each with its `tag` property first.
    case taggedUnion(name: String, description: String?, tag: String, variants: [(tagValue: String, schema: JSONSchema)])
    /// The value may be `null`; as a property it may also be absent.
    case nullable(JSONSchema)
    /// The schema plus the JSON Schema keywords of the rules, such as `minLength`.
    case constrained(JSONSchema, by: [ValidationRule])

    /// The schema of a union case's associated value, e.g. `.associatedValue(of: Self.text)` for `case text(String)`.
    ///
    /// Takes the case rather than the type so generated code never has to name the type, which may not be visible from
    /// an extension of a nested enum.
    public static func associatedValue<Value: SchemaRepresentable, Union>(of makeCase: (Value) -> Union) -> JSONSchema {
        Value.jsonSchema
    }

    /// The rules of a nullable schema constrain its non-null value, and item rules constrain an array's items.
    private func constrained(by rules: [ValidationRule]) -> JSONSchema {
        if rules.isEmpty { return self }
        if case .nullable(let wrapped) = self { return .nullable(wrapped.constrained(by: rules)) }

        let itemRules = rules.forItems
        guard !itemRules.isEmpty, case .array(let items) = self else { return .constrained(self, by: rules) }
        let ownRules = rules.filter { rule -> Bool in
            if case .items = rule { false } else { true }
        }
        return JSONSchema.array(items: items.constrained(by: itemRules)).constrained(by: ownRules)
    }

    public struct Property: Sendable {
        /// The JSON key.
        public let key: String
        public let schema: JSONSchema
        public let description: String?
        /// The property's initial value, which it keeps when the JSON leaves the key out. `strict()` writes it as the
        /// property's `default`.
        public let defaultValue: JSONValue?

        public init<Value: SchemaRepresentable>(
            _ key: String,
            _ type: Value.Type,
            description: String? = nil,
            rules: [ValidationRule] = [],
            default defaultValue: JSONValue? = nil
        ) {
            self.key = key
            self.schema = Value.jsonSchema.constrained(by: rules)
            self.description = description
            self.defaultValue = defaultValue
        }

        /// False for an optional property and for one with a default.
        public var isRequired: Bool {
            if case .nullable = schema { false } else { defaultValue == nil }
        }
    }
}
